/* the calls that are not simply passed on */
static int q_threaded(void) { return q_on ? 1 : q_in->threaded(); }
static void q_thread_start(void)
{
    q_in->thread_start();
    if (!q_on && q_start())
        fprintf(stderr, "[VK] draws recorded on a thread of their own (RECOMP_VK_RECORD_THREAD=0: on the renderer's)\n");
}
/* every 600 frames, after the backend's own [VK] lines: the recording thread */
static void q_report(void)
{
    static uint64_t l_busy;
    double fq = 1000.0 / (double)SDL_GetPerformanceFrequency();
    uint64_t busy = atomic_load(&q_busy_t);
    int top[3] = { -1, -1, -1 }, i, j;
    char tb[256] = "";
    for (i = 0; i < RB_NCALLS_Q; i++) {
        if (!q_drain_by[i]) continue;
        for (j = 0; j < 3; j++)
            if (top[j] < 0 || q_drain_t_by[i] > q_drain_t_by[top[j]]) {
                memmove(top + j + 1, top + j, (size_t)(2 - j) * sizeof *top);
                top[j] = i; break;
            }
    }
    for (j = 0; j < 3 && top[j] >= 0; j++) {
        size_t k = strlen(tb);
        snprintf(tb + k, sizeof tb - k, "%s %s %llu (%.1f ms)", j ? "," : "; most:", q_names[top[j]],
                 (unsigned long long)q_drain_by[top[j]], (double)q_drain_t_by[top[j]] * fq);
    }
    fprintf(stderr, "[VK]   recording thread: %.0f ms busy, %llu calls (%.1f MB); the renderer waited for it %llu times, %.1f ms in all%s%s; %llu fence waits answered at once\n",
            (double)(busy - l_busy) * fq, (unsigned long long)q_n_async, (double)q_bytes / 1048576.0,
            (unsigned long long)q_n_drain, (double)q_drain_t * fq, tb,
            q_n_space ? "; the queue was full" : "", (unsigned long long)q_n_fence_fast);
    l_busy = busy;
    q_n_async = q_bytes = q_n_drain = q_drain_t = q_n_space = q_n_fence_fast = 0;
    memset(q_drain_by, 0, sizeof q_drain_by);
    memset(q_drain_t_by, 0, sizeof q_drain_t_by);
}
static int q_window_present(const RbFrame *f)
{
    static uint64_t frames;
    int r;
    if (q_on) q_drain(43);
    r = q_in->window_present(f);
    q_sc_forget();                     /* it forgets the bound scissor */
    if (q_on && ++frames % 600 == 0)
        q_report();
    return r;
}

